    public ExpectedException expectedException = ExpectedException.none();

    @BeforeClass
    public static void setUp() throws Exception {
        URL url = CSVRecordIteratorTest.class.getResource(TEST_FILE);
        inputStream = Files.newInputStream(Path.of(url.toURI()));
        reader = new InputStreamReader(inputStream, UTF8);
        parser = new CSVParserBuilder().withSeparator('\t').build();
        iterator = parser.parse(reader).iterator();
    }

    @AfterClass
    public static void tearDown() throws Exception {
        if (inputStream != null) {
            inputStream.close();
        }
    }

    @Test
    public void testHasNext_whenIteratorIsNotEmpty_shouldReturnTrue() {
        Assert.assertTrue(iterator.hasNext());
    }

    @Test
    public void testHasNext_whenIteratorIsEmpty_shouldReturnFalse() {
        // Move to the end of the iterator
        while (iterator.hasNext()) {
            iterator.next();
        }
        Assert.assertFalse(iterator.hasNext());
    }

    @Test
    public void testNext_whenIteratorIsNotEmpty_shouldReturnNextRecord() {
        CSVRecord record = iterator.next();
        // Check that the record has the correct number of tokens
        assertThat(record.toMap().size(), is(5));
        // Check that the first token is "Name"
        assertThat(record.get(0), is("Name"));
    }

    @Test(expected = NoSuchElementException.class)
    public void testNext_whenIteratorIsEmpty_shouldThrowNoSuchElementException() {
        // Move to the end of the iterator
        while (iterator.hasNext()) {
            iterator.next();
        }
        iterator.next();
    }

    @Test
    public void testRemove_shouldThrowUnsupportedOperationException() {
        expectedException.expect(UnsupportedOperationException.class);
        iterator.remove();
    }
}
